theorem chartSupport_cover : ({z : EulerSobolev.Domain 4 | |z 0| ≤ 2 * period}) ⊆
    ⋃ i : Fin 6, {z : Domain 4 | z 0 ∈
      Set.Ioc (((i : ℝ)-3)*period) ((((i : ℝ)-3)*period)+period)}

theorem mollifyJet_sobolevNorm_tendsto {directions : Fin 4 → LiftTangent} {s : ℕ} {f : LiftL2 period}
    (J : SpatialJet period directions s f) :
    Filter.Tendsto (fun n => ((mollifyJet period J n).sub J).sobolevNorm) Filter.atTop (𝓝 0)

theorem mollifyJet_word {directions : Fin 4 → LiftTangent} {s k : ℕ} {f : LiftL2 period}
    (J : SpatialJet period directions s f) (n : ℕ) (w : Fin k → Fin 4) :
    (mollifyJet period J n).word w = mollify period n (J.word w)

theorem mollifyJet_word_tendsto {directions : Fin 4 → LiftTangent} {s k : ℕ} {f : LiftL2 period}
    (J : SpatialJet period directions s f) (w : Fin k → Fin 4) :
    Filter.Tendsto (fun n => (mollifyJet period J n).word w) Filter.atTop (𝓝 (J.word w))

theorem sub_word {directions : Fin 4 → LiftTangent} {s k : ℕ} {f g : LiftL2 period}
    (J : SpatialJet period directions s f) (K : SpatialJet period directions s g)
    (w : Fin k → Fin 4) : (J.sub K).word w = J.word w - K.word w

theorem contDiff_projectedOperator (G : ℝ → E →L[ℝ] E) {n : ℕ∞ω}
    (hreg : ContDiff ℝ n G) :
    ContDiff ℝ n (fun t => projectedOperator S (G t))

theorem boundLevel_truncate {s n : ℕ} {A : SmoothCoefficient period}
    (K : CoefficientJet period directions (s + 1) A) (hn : n ≤ s) :
    boundLevel period K.truncate n = boundLevel period K n

theorem levelNorm_add_le {s n : ℕ} {f g : LiftL2 period}
    (J : SpatialJet period directions s f) (K : SpatialJet period directions s g) :
    levelNorm period (J.add K) n ≤ levelNorm period J n + levelNorm period K n

theorem levelNorm_truncate {s n : ℕ} {f : LiftL2 period}
    (J : SpatialJet period directions (s + 1) f) (hn : n ≤ s) :
    levelNorm period J.truncate n = levelNorm period J n

theorem word_add {s n : ℕ} {f g : LiftL2 period}
    (J : SpatialJet period directions s f) (K : SpatialJet period directions s g)
    (w : Fin n → Fin 4) : (J.add K).word w = J.word w + K.word w

theorem pressure_pairing_zero (κ : ℝ) (m : Vector3) {p e : LiftL2 period}
    (hp : p ∈ gradientSpace period κ m) (he : e ∈ divergenceFreeSpace period κ m) :
    ⟪p, e⟫_ℝ = 0

theorem testGradient_pairing_zero (κ : ℝ) (m : Vector3) {g e : LiftL2 period}
    (hg : g ∈ ({g : EulerLiftedGradientSpace.LiftL2 period | ∃ φ : EulerLiftedGradientSpace.LiftDomain period → ℝ, (HasCompactSupport φ ∧ ∀ x, ContDiff ℝ ∞ (EulerLiftedGradientSpace.localLift period φ x)) ∧ g =ᵐ[EulerLiftedGradientSpace.liftMeasure period] EulerLiftedGradientSpace.liftedGradient period κ m φ})) (he : e ∈ divergenceFreeSpace period κ m) :
    ⟪g, e⟫_ℝ = 0

theorem riccatiRoot_bounds {ε t : ℝ}
    (hy : 0 ≤ 1 - ε * t ∧ 1 - ε * t ≤ 1) :
    1 ≤ riccatiRoot ε t ∧ riccatiRoot ε t ≤ 2

theorem two_column_bound {a b c d x y C : ℝ}
    (h1 : |a| + |c| ≤ C) (h2 : |b| + |d| ≤ C) :
    |a * x + b * y| + |c * x + d * y| ≤ C * (|x| + |y|)

theorem three_term_bound {a b c p q n e : ℝ}
    (ha : |a| ≤ e) (hb : |b| ≤ e) (hc : |c| ≤ e) :
    |a * p + b * q + c * n| ≤ e * norm3 p q n

theorem pressureConstant_nonneg {n : ℕ} {A : SmoothCoefficient period}
    (J : CoefficientJet period directions n A) (c : ℝ) (hc : 0 < c) :
    0 ≤ J.pressureConstant c

theorem add_norm_le {n : ℕ} {f g : LiftL2 period}
    (J : SpatialJet period directions n f) (K : SpatialJet period directions n g) :
    (J.add K).sobolevNorm ≤ J.sobolevNorm + K.sobolevNorm

theorem multiply_norm_le {n : ℕ} {A : SmoothCoefficient period} {f : LiftL2 period}
    (K : CoefficientJet period directions n A) (J : SpatialJet period directions n f) :
    (multiply K J).sobolevNorm ≤ K.productConstant * J.sobolevNorm

theorem sobolevNorm_eq_sum_words {s : ℕ} {f : LiftL2 period}
    (J : SpatialJet period directions s f) :
    J.sobolevNorm = ∑ n ∈ Finset.range (s + 1), ∑ w : Fin n → Fin 4, ‖J.word w‖

theorem sub_norm_le {n : ℕ} {f g : LiftL2 period}
    (J : SpatialJet period directions n f) (K : SpatialJet period directions n g) :
    (J.sub K).sobolevNorm ≤ J.sobolevNorm + K.sobolevNorm

theorem truncate_norm_le {n : ℕ} {f : LiftL2 period}
    (J : SpatialJet period directions (n + 1) f) :
    J.truncate.sobolevNorm ≤ J.sobolevNorm

theorem blockNorm_truncate {s q n : ℕ} {f : LiftL2 period}
    (J : EulerSpatialSobolevInverse.SpatialJet period directions (s + 1) f) (h : n + q ≤ s) :
    blockNorm period J.truncate q n = blockNorm period J q n

theorem blockNorm_zero_eq_size {s q : ℕ} {f : LiftL2 period}
    (J : EulerSpatialSobolevInverse.SpatialJet period directions s f) (h : q ≤ s) :
    blockNorm period J q 0 = sobolevSize period (directions := directions) q f

theorem coefficientBlock_nonneg {s q n : ℕ} {A : SmoothCoefficient period}
    (K : EulerSpatialSobolevInverse.CoefficientJet period directions s A) :
    0 ≤ coefficientBlock period K q n

theorem coefficientBlock_truncate {s q n : ℕ} {A : SmoothCoefficient period}
    (K : EulerSpatialSobolevInverse.CoefficientJet period directions (s + 1) A) (h : n + q ≤ s) :
    coefficientBlock period K.truncate q n = coefficientBlock period K q n

theorem sobolevSize_eq {q : ℕ} {f : LiftL2 period}
    (J : EulerSpatialSobolevInverse.SpatialJet period directions q f) :
    sobolevSize period (directions := directions) q f = J.sobolevNorm

theorem commutatorBlock_nonneg {s q n : ℕ} {A : SmoothCoefficient period} {f : LiftL2 period}
    (K : EulerSpatialSobolevInverse.CoefficientJet period directions s A)
    (J : EulerSpatialSobolevInverse.SpatialJet period directions s f) : 0 ≤ commutatorBlock K J q n

theorem commutatorBlock_zero {s q : ℕ} {A : SmoothCoefficient period} {f : LiftL2 period}
    (K : EulerSpatialSobolevInverse.CoefficientJet period directions s A)
    (J : EulerSpatialSobolevInverse.SpatialJet period directions s f) : commutatorBlock K J q 0 = 0

theorem baseWordMetric_le_sobolevNorm {s : ℕ} {f : LiftL2 period}
    (K : LiftL2 period →L[ℝ] LiftL2 period) (J : SpatialJet period standardDirection s f) :
    baseWordMetricNorm period K J ≤ Real.sqrt ‖K‖ * J.sobolevNorm

theorem sum_baseWordValues_norm {s : ℕ} {f : LiftL2 period}
    (J : SpatialJet period standardDirection s f) :
    (∑ w : BaseWord s, ‖baseWordValues period J w‖) = J.sobolevNorm

theorem gradient_memLp {φ : Space → ℝ}
    (hc : HasCompactSupport φ) (hs : ContDiff ℝ ∞ φ) :
    MemLp (gradient φ) 2 (volume : Measure Space)

theorem TreeBound.pressureConstant_le {s : ℕ} {A : SmoothCoefficient P}
    {K : CoefficientJet P dirs s A} {B : ℝ} (hK : TreeBound K B)
    (c : ℝ) (hc : 0 < c) (hB : 0 ≤ B) : K.pressureConstant c ≤ pressureCost c B s

theorem TreeBound.productConstant_le {s : ℕ} {A : SmoothCoefficient P}
    {K : CoefficientJet P dirs s A} {B : ℝ} (hK : TreeBound K B) :
    K.productConstant ≤ productCost B s

theorem TreeBound.restrict {s : ℕ} {A : SmoothCoefficient P}
    {K : CoefficientJet P dirs s A} {B : ℝ} (hK : TreeBound K B)
    (q : ℕ) (hq : q ≤ s) : TreeBound (EulerH6Pressure.CoefficientJet.restrict K q hq) B

theorem TreeBound.truncate {s : ℕ} {A : SmoothCoefficient P}
    {K : CoefficientJet P dirs (s+1) A} {B : ℝ} (hK : TreeBound K B) :
    TreeBound K.truncate B

theorem deriv_time_slice {u : ℝ × Space → Space} {t : ℝ} {x : Space}
    (hu : DifferentiableAt ℝ u (t, x)) :
    deriv (fun r => u (r, x)) t = fderiv ℝ u (t, x) (1, 0)

theorem time_deriv_differentiableAt {u : ℝ × Space → Space} {t : ℝ} {x : Space}
    (hu : ContDiffAt ℝ 2 u (t, x)) :
    DifferentiableAt ℝ (fun y => deriv (fun r => u (r, y)) t) x

theorem partialDerivative_add {f g : Space → ℝ} {x : Space}
    (hf : DifferentiableAt ℝ f x) (hg : DifferentiableAt ℝ g x) (i : Fin 3) :
    partialDerivative (f + g) i x = partialDerivative f i x + partialDerivative g i x

theorem partialDerivative_mul {f g : Space → ℝ} {x : Space}
    (hf : DifferentiableAt ℝ f x) (hg : DifferentiableAt ℝ g x) (i : Fin 3) :
    partialDerivative (f * g) i x = g x * partialDerivative f i x + f x * partialDerivative g i x

theorem orbits_tendstoUniformly (τ : P → E →ₗᵢ[ℝ] E) {ι : Type*} {l : Filter ι}
    (u : ι → E) (v : E) (hu : Tendsto u l (𝓝 v)) :
    TendstoUniformly (fun n a => τ a (u n)) (fun a => τ a v) l

theorem translation_orbits_tendstoUniformly {ι : Type*} {l : Filter ι}
    (u : ι → L2Space V) (v : L2Space V) (hu : Tendsto u l (𝓝 v)) :
    TendstoUniformly (fun n a => translation a (u n)) (fun a => translation a v) l

theorem cylinderHeatJet_word {q n : ℕ} {f : LiftL2 period}
    (J : SpatialJet period standardDirection q f) (v : ℝ≥0) (w : Fin n → Fin 4) :
    (cylinderHeatJet period J v).word w = cylinderHeat period v (J.word w)

theorem pullbackMeanOperator_contDiff {n : ℕ∞ω}
    (hD : ContDiff ℝ n D) (hH : ContDiff ℝ n H) (hC : ContDiff ℝ n C) :
    ContDiff ℝ n (fun p => transportedOperator (D p) (meanOperator J R (H p) (C p)))

theorem norm_hasDerivAt {f : ℝ → E} {f' : E} {t : ℝ}
    (hf : HasDerivAt f f' t) (hft : f t ≠ 0) :
    HasDerivAt (fun s => ‖f s‖) (⟪f t,f'⟫_ℝ / ‖f t‖) t

theorem norm_hasDerivWithinAt {f : ℝ → E} {f' : E} {t : ℝ} {S : Set ℝ}
    (hf : HasDerivWithinAt f f' S t) (hft : f t ≠ 0) :
    HasDerivWithinAt (fun s => ‖f s‖) (⟪f t,f'⟫_ℝ / ‖f t‖) S t

theorem normalized_ray_hasDerivAt (B : E →L[ℝ] E) {m : ℝ → E} {t : ℝ}
    (hm : HasDerivAt m (-B.adjoint (m t)) t) (hm0 : m t ≠ 0) :
    HasDerivAt (fun s => unit (m s)) (rayRate B (unit (m t))) t

theorem normalized_ray_hasDerivWithinAt (B : E →L[ℝ] E) {m : ℝ → E} {t : ℝ} {S : Set ℝ}
    (hm : HasDerivWithinAt m (-B.adjoint (m t)) S t) (hm0 : m t ≠ 0) :
    HasDerivWithinAt (fun s => unit (m s)) (rayRate B (unit (m t))) S t

theorem SliceDifferentiable.add {s : Set ℝ} {f g : Domain → E} {z : Domain}
