theorem bounds_of_accumulated_error {e : ℕ → ℝ} {η v : ℝ}
    (he : SmallSeries e η) (hη : η ≤ 1/4) (n : ℕ)
    (hv : |v-1| ≤ 2*∑ i ∈ range n, e i) : 1/2 ≤ v ∧ v ≤ 2

theorem stage_congr_at {J D : ℕ} {C c X K : ℝ} {a β b γ : ℕ → ℝ} {n : ℕ}
    (G : StageGuards J D C c X K a β n) (ha : a n=b n) (hβ : β n=γ n) :
    StageGuards J D C c X K b γ n

theorem displacement_comp_le (X Y : E → E) {M δ : ℝ}
    (hX : ∀ x, ‖X x - x‖ ≤ M) (hY : ∀ x, ‖Y x - x‖ ≤ δ) (x : E) :
    ‖X (Y x) - x‖ ≤ M + δ

theorem UnitHolomorphic.degreeZeroJet_continuous {I : Window} {ρ : ℝ} {f : ℂ → ℂ}
    (hf : UnitHolomorphic I ρ f) (hρ : 0 < ρ) (n m : ℕ) :
