theorem UnitHolomorphic.norm_toAxisSpace_le {I : Window} {ε ρ : ℝ} {f : ℂ → ℂ}
    (hf : UnitHolomorphic I ρ f) (hε : 0 < ε) (hερ : ε < ρ) :
