theorem norm_cauchyCoefficient_le {f : ℂ → ℂ} {c : ℂ} {ρ : ℝ}
    (hρ : 0 < ρ) (hb : ∀ z ∈ sphere c ρ, ‖f z‖ ≤ 1) (m : ℕ) :
