theorem normalizedExp_re_of_real {F : ℂ → ℂ} {Λ C x : ℝ}
    (hreal : (F (x : ℂ)).im = 0) :
    (normalizedExp F Λ C (x : ℂ)).re = Real.exp (Λ * (F (x : ℂ)).re) / C

theorem re_le_realPartSup {F : ℂ → ℂ} {K : Set ℂ}
