theorem even_localized {a A R : ℝ} (hA : 0 < A) (hR : 0 < R) {F : Plane → E}
    (he : ∀ p ∈ Ioo (a - A) (a + A), ∀ r ∈ Ioo (-R) R, F (p, -r) = F (p, r)) :
