    (hA : DerivativeShape A₁) (F : Field) :
    letter A₀ A₁ true (letter A₀ A₁ true F) = 0

theorem derivativeLetter_of_lowZero (A₀ : Coeff) {A₁ : Coeff}
    (hA : DerivativeShape A₁) {F : Field} (hF : LowZero F) :
