theorem regularPrimitive_evaluate (c : ℕ) {R : ℝ} {f : ℝ → C(K, E)}
    (hf : ContinuousOn f (radialDomain R)) {r : ℝ} (hr : r ∈ radialDomain R) (z : K) :
